#!/usr/bin/env python3
"""Pack original Bongo Cat layers as LVGL I8 images with bounded decode RAM."""
from pathlib import Path

from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
ASSETS = ROOT / "src/display/assets/bongo_cat"
WIDTH, HEIGHT = 192, 96
BASE_TILE_HEIGHT = 32


def load(name):
    return Image.open(ASSETS / f"{name}.png").convert("RGBA").resize(
        (WIDTH, HEIGHT), Image.Resampling.LANCZOS
    ).quantize(colors=256, method=Image.Quantize.FASTOCTREE)


def main():
    output = [
        "/* Generated by scripts/convert-bongo-cat.py. Do not edit.",
        " * Artwork attribution and MIT license: assets/bongo_cat/ */",
        '#include "bongo_cat.h"',
        "",
    ]
    total = 0

    def emit(name, indexed, box):
        nonlocal total
        image = indexed.crop(box)
        w, h = image.size
        # LVGL indexed palettes are ARGB8888: BGRA bytes on little-endian ARM.
        palette = indexed.getpalette("RGBA")
        palette += [0] * (1024 - len(palette))
        data = bytearray()
        for i in range(0, 1024, 4):
            r, g, b, a = palette[i:i + 4]
            data.extend((b, g, r, a))
        data.extend(image.tobytes())
        total += len(data)
        # Each individual image is decoded to ARGB8888. Keep it below 24 KB;
        # never require a full 192x96 (73 KB) decoded image in the LVGL heap.
        assert w * h * 4 <= 24576
        output.append(f"static const uint8_t {name}[] __attribute__((aligned(4))) = {{")
        for start in range(0, len(data), 24):
            output.append("    " + ", ".join(f"0x{v:02x}" for v in data[start:start + 24]) + ",")
        output.extend(["};", ""])
        return (
            "    { .image = { .header.magic = LV_IMAGE_HEADER_MAGIC,\n"
            "        .header.cf = LV_COLOR_FORMAT_I8,\n"
            f"        .header.w = {w}, .header.h = {h}, .header.stride = {w},\n"
            f"        .data_size = sizeof({name}), .data = {name} }},\n"
            f"      .x = {box[0]}, .y = {box[1]} }},"
        )

    base = load("base")
    x0, y0, x1, y1 = base.convert("RGBA").getbbox()
    bases = []
    for n, y in enumerate(range(y0, y1, BASE_TILE_HEIGHT)):
        bases.append(emit(f"base_{n}", base, (x0, y, x1, min(y + BASE_TILE_HEIGHT, y1))))
    assert len(bases) == 3
    paws = []
    # Upstream names describe the cat's anatomy, not screen left/right.
    for side, name in enumerate(("right", "left")):
        states = []
        for state, suffix in enumerate(("up", "down")):
            image = load(f"{name}-{suffix}")
            states.append(emit(f"paw_{side}_{state}", image, image.convert("RGBA").getbbox()))
        paws.append(states)
    output.extend(["const struct pinchwing_bongo_sprite pinchwing_bongo_base[3] = {", *bases, "};", ""])
    output.append("const struct pinchwing_bongo_sprite pinchwing_bongo_paws[2][2] = {")
    for states in paws:
        output.extend(["  {", *states, "  },"])
    output.extend(["};", ""])
    (ROOT / "src/display/bongo_cat.c").write_text("\n".join(output))
    preview = Image.new("RGBA", (WIDTH * 2, HEIGHT * 2), "#07101c")
    for mask in range(4):
        image = base.convert("RGBA")
        for name, bit in (("right", 1), ("left", 2)):
            image.alpha_composite(load(f"{name}-{'down' if mask & bit else 'up'}").convert("RGBA"))
        preview.alpha_composite(image, ((mask % 2) * WIDTH, (mask // 2) * HEIGHT))
    (ROOT / "build").mkdir(exist_ok=True)
    preview.save(ROOT / "build/bongo-cat-preview.png")
    print(f"Sprite data: {total:,} bytes (previous full-pose data: 221,184)")


if __name__ == "__main__":
    main()
